    vec2 uv = fragCoord.xy / iResolution.xy;
    vec3 color = texture(iChannel0, uv).rgb;
    fragColor = vec4(color, 1.0);
}

// Buffer A
float random(vec2 seed) {
    return fract(sin(dot(seed.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  if (iMouse.z > 0.0) {
    vec2 uv = floor(fragCoord.xy / iResolution.xy * 64.0) / 64.0;
    float randValue2 = random(uv + iTime);
    float v = length(uv - vec2(0.5,0.5)) < 0.2 && randValue2 > 0.2 ? 1.0 : 0.0;
    fragColor = vec4(v, v, v, 1.0);
  } else {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 rightUv = mod(uv + vec2(1.0 / iResolution.x, 0.0),1.0);
    vec2 leftUv =mod(uv + vec2(-1.0 / iResolution.x, 0.0),1.0);
    vec2 topUv = mod(uv + vec2(0.0, 1.0 / iResolution.y),1.0);
    vec2 bottomUv = mod(uv + vec2(0.0, -1.0 / iResolution.y),1.0);
    vec2 lefttopUv =mod(uv + vec2(-1.0 / iResolution.x, 1.0 / iResolution.y),1.0);
    vec2 righttopUv = mod(uv + vec2(1.0 / iResolution.x, 1.0 / iResolution.y),1.0);
    vec2 leftbottomUv = mod(uv + vec2(-1.0 / iResolution.x, -1.0 / iResolution.y),1.0);
    vec2 rightbottomUv = mod(uv + vec2(1.0 / iResolution.x, -1.0 / iResolution.y),1.0);

    int n = 0;

    n = n + int(texture(iChannel0, rightUv).x);
    n = n + int(texture(iChannel0, leftUv).x);
    n = n + int(texture(iChannel0, topUv).x);
    n = n + int(texture(iChannel0, bottomUv).x);
    n = n + int(texture(iChannel0, lefttopUv).x);
    n = n + int(texture(iChannel0, righttopUv).x);
    n = n + int(texture(iChannel0, leftbottomUv).x);
    n = n + int(texture(iChannel0, rightbottomUv).x);

    fragColor = vec4(texture(iChannel0, fragCoord.xy / iResolution.xy).rgb,1.0);
    if (fragColor.x == 0.0){
      if (n == 3){
        fragColor = vec4(1.0,1.0,1.0,1.0);
      }
    } else {
      if (n >= 4 || n <= 1) {
        fragColor = vec4(0.0,0.0,1.0,1.0);
      }
    }
  }
}
